import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    parsed = json.loads(json_data)
    if unknown_key not in parsed:
        raise ValueError(f"Key '{unknown_key}' not found in JSON data.")
    url = parsed[unknown_key]
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from {url}: {e}")
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
    filename = f"{unknown_key}_{timestamp}.txt"
    if save_dir:
        full_path = os.path.join(save_dir, filename)
    else:
        full_path = filename
    with open(full_path, 'w', encoding='utf-8') as f:
        f.write(resp.text)
    return os.path.abspath(full_path)

